// ============================================================================
// CLASSIFICAR D1 — traduz as fontes fiscais em categorias (nunca em pontos).
//
// PGFN — quem decide o quê:
//   • EXISTÊNCIA da dívida  -> Econodata (campos que o Orquestrador manda).
//                              É a FONTE DE VERDADE: null/0 = não há dívida.
//   • CLASSIFICAÇÃO da dívida -> CND/CPEN Federal da Infosimples.
//                              Só é consultada quando existe dívida.
//
// Ou seja: sem dívida no Econodata, o t_pgfn é 'Não' mesmo que a certidão
// diga outra coisa. Com dívida, a certidão define se é regularizada
// (Parcelada/garantida) ou exigível (Irregular).
// ============================================================================

const cndOriginal = $('Infosimples · CND Federal (Resultado Final)').first().json;
const cnd = cndOriginal.data?.[0] ?? null;   // null = a Infosimples não emitiu a certidão
const est = $('Direct Data · CND Estadual').first().json.retorno ?? null;

// Sintonia: 'A+' pode vir do Selo Sintonia OU da lista do Confia (fallback).
// A pontuação é a mesma; sintonia_fonte diz qual das duas decidiu.
const sintoniaCls = $('Classificar Sintonia').first().json ?? {};
const t_sintonia = sintoniaCls.t_sintonia ?? 'ND';
const sintonia_fonte = sintoniaCls.sintonia_fonte ?? 'nenhum';
const confia_lista_origem = sintoniaCls.confia_lista_origem ?? 'nao_consultada';

const entrada = $('When Executed by Another Workflow').first().json;

// ---------------------------------------------------------------------------
// Dívida ativa da União (Econodata, via Orquestrador)
// Se o Orquestrador não mandar os campos, chegam undefined -> null.
// ---------------------------------------------------------------------------
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const divida_uniao_qtde = num(entrada.divida_uniao_qtde);
const divida_uniao_valor_total = num(entrada.divida_uniao_valor_total);
const divida_uniao_pct_faturamento = num(entrada.divida_uniao_pct_faturamento);

// Existe dívida registrada? 0 NÃO conta (o Econodata devolve 0 quando não há dívida),
// e null também não (campo ausente -> assume 'Não' por decisão da BMS).
const temDividaUniao = (divida_uniao_qtde ?? 0) > 0 || (divida_uniao_valor_total ?? 0) > 0;

// ---------------------------------------------------------------------------
// t_cnd — categoria da certidão federal, independente do PGFN.
// Fica 'ND' quando a Infosimples não conseguiu emitir.
// ---------------------------------------------------------------------------
const tipo = cnd?.tipo || '';
let t_cnd = 'ND';
if (cnd) {
  if (tipo.includes('efeitos de negativa')) t_cnd = 'Positiva c/ efeitos de negativa';
  else if (tipo === 'Positiva') t_cnd = 'Positiva';   // débito exigível, sem regularização
  else if (tipo === 'Negativa') t_cnd = 'Negativa';   // nada em aberto
}

// ---------------------------------------------------------------------------
// t_pgfn — dívida ativa da União
// ---------------------------------------------------------------------------
let t_pgfn = 'Não';
let pgfn_fonte = 'econodata_sem_divida';  // rastreabilidade de qual regra decidiu
let pgfn_divergencia = false;             // Econodata x certidão se contradizem

if (!temDividaUniao) {
  // ---- SEM DÍVIDA (null, ausente ou 0) — fonte de verdade é o Econodata ----
  t_pgfn = 'Não';
  pgfn_fonte = (divida_uniao_qtde === null && divida_uniao_valor_total === null)
    ? 'sem_dado_assumido_nao'   // campo não chegou -> assume 'Não'
    : 'econodata_sem_divida';   // chegou 0 -> confirmadamente sem dívida

} else if (!cnd) {
  // ---- COM DÍVIDA, mas a certidão não saiu --------------------------------
  // Sem a certidão não há como saber se está exigível; por decisão da BMS,
  // classifica no grau mais brando (não penaliza por falha de coleta).
  t_pgfn = 'Parcelada/garantida';
  pgfn_fonte = 'divida_sem_certidao';

} else if (cnd.debitos_pgfn !== true || t_cnd === 'Negativa') {
  // ---- COM DÍVIDA, mas a certidão está limpa ------------------------------
  // A certidão é do dia; a Lista de Devedores da PGFN (Econodata) é snapshot
  // trimestral. A certidão ganha, mas fica registrada a divergência para o
  // analista conferir na revisão manual.
  t_pgfn = 'Não';
  pgfn_fonte = 'certidao_limpa_divergente';
  pgfn_divergencia = true;

} else if (tipo.includes('efeitos de negativa')) {
  // ---- COM DÍVIDA + certidão positiva c/ efeitos de negativa --------------
  // Dívida existe mas está parcelada, garantida ou com exigibilidade suspensa.
  t_pgfn = 'Parcelada/garantida';
  pgfn_fonte = 'cnd_efeitos_negativa';

} else {
  // ---- COM DÍVIDA + certidão positiva pura --------------------------------
  // Débito exigível, sem regularização. Único caminho que gera 'Irregular'.
  t_pgfn = 'Irregular';
  pgfn_fonte = 'cnd_positiva';
}

// ---------------------------------------------------------------------------
// CND Estadual (Direct Data) — independente do federal.
// possuiDebito=false                      -> Regular
// possuiDebito=true + efeitoNegativa=true -> Regular (exigibilidade suspensa)
// possuiDebito=true sem efeito negativa   -> Irregular
// est null (API falhou)                   -> ND
// ---------------------------------------------------------------------------
let t_est = 'ND';
if (est) {
  t_est = (!est.possuiDebito || est.efeitoNegativa) ? 'Regular' : 'Irregular';
}

// ---------------------------------------------------------------------------
// GATE G3 — reprovação automática: certidão federal POSITIVA pura + dívida
// ativa irregular. Só dispara quando há dívida no Econodata E a certidão saiu
// positiva pura (as duas condições vêm do mesmo caminho 'cnd_positiva').
// ---------------------------------------------------------------------------
const gateDisparado = (t_cnd === 'Positiva' && t_pgfn === 'Irregular')
  ? 'G3: CND federal positiva + PGFN irregular'
  : null;

return [{
  json: {
    // ---- contrato de classificação (o Orquestrador pontua a partir disto) --
    t_cnd,
    t_pgfn,
    t_est,
    t_sintonia,
    sintonia_fonte,        // selo_sintonia | confia_protocolo | nenhum
    confia_lista_origem,   // site | site+snapshot | snapshot_local | nao_consultada
    gate_disparado: gateDisparado,

    // ---- dado de exibição (Lovable) ---------------------------------------
    pgfn_fonte,          // econodata_sem_divida | sem_dado_assumido_nao | divida_sem_certidao
                         // | certidao_limpa_divergente | cnd_efeitos_negativa | cnd_positiva
    pgfn_divergencia,    // true = certidão limpa mas Econodata acusa dívida
    divida_uniao_qtde,
    divida_uniao_valor_total,
    divida_uniao_pct_faturamento,

    // ---- auditoria --------------------------------------------------------
    cnpj_consultado: (() => {
      // Se houve retry de matriz real, o CNPJ consultado de fato é o do retry.
      try { return $('Extrair CNPJ Matriz Real do Erro').first().json.cnpj_matriz_real; }
      catch (e) { return $('Normalizar CNPJ Matriz').first().json.cnpj_matriz; }
    })(),
    retry_matriz_real: (() => {
      try { $('Extrair CNPJ Matriz Real do Erro').first(); return true; }
      catch (e) { return false; }
    })(),
    cnd_code: cndOriginal?.code ?? null,
    cnd_erro: (!cnd && Array.isArray(cndOriginal?.errors) && cndOriginal.errors.length) ? String(cndOriginal.errors[0]) : null,
  }
}];

// Normaliza o CNPJ para a MATRIZ (raiz + 0001 + DV recalculado).
// Motivo: a CND Federal (RFB/PGFN) so e emitida para o CNPJ da matriz.
// Chamar com o CNPJ de uma filial retorna code 620:
//   "A certidao deve ser emitida para o CNPJ da matriz - 10.483.444/0001-89"
// A certidao da matriz abrange todos os estabelecimentos (filiais), entao
// o resultado e valido para o fornecedor consultado.
//
// Suporta o CNPJ alfanumerico (regra oficial: valor do caractere = ASCII - 48).

const raw = String($json.cnpj || '')
  .toUpperCase()
  .replace(/[^0-9A-Z]/g, '')
  .padStart(14, '0');

const raiz = raw.substring(0, 8);
const base = raiz + '0001';

const val = (c) => c.charCodeAt(0) - 48;
const calcDV = (str, pesos) => {
  const soma = str.split('').reduce((acc, c, i) => acc + val(c) * pesos[i], 0);
  const resto = soma % 11;
  return resto < 2 ? 0 : 11 - resto;
};

const d1 = calcDV(base, [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]);
const d2 = calcDV(base + d1, [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]);

const cnpj_matriz = `${base}${d1}${d2}`;
const eh_filial = raw.substring(8, 12) !== '0001';

return [{
  json: {
    ...$json,
    cnpj_original: raw,
    cnpj_matriz,
    eh_filial,
  }
}];

// Ponto unico de referencia pro resultado final da CND Federal,
// venha ele do caminho normal (sem retry) ou do retry de matriz real.
// So um dos dois ramos roda, entao so um item chega aqui.
return [{ json: $json }];

// Extrai o CNPJ real da matriz a partir do texto do erro 620, ex:
// "A certidao deve ser emitida para o CNPJ da matriz - 02.914.460/0112-76"
// Isso cobre o caso em que a ordem 0001 (calculada) nao e a matriz de fato
// -- CNPJs antigos/reestruturados podem ter a matriz registrada em outra
// ordem. A Infosimples/Receita sempre devolve o CNPJ certo no proprio erro.

const msg = ($json.errors && $json.errors[0]) || '';
const match = msg.match(/(\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2})/);
const cnpj_matriz_real = match ? match[1].replace(/[^0-9]/g, '') : null;

return [{
  json: {
    ...$('Normalizar CNPJ Matriz').first().json,
    cnpj_matriz_real,
  }
}];

// ============================================================================
// CLASSIFICAR SINTONIA — conformidade cooperativa junto a Receita Federal.
//
// Fonte 1 (principal): Selo Sintonia A+ (API publica da RFB).
// Fonte 2 (FALLBACK):  lista de protocolos do programa Confia
//                      (https://www.gov.br/receitafederal/.../confia/protocolos)
//
// Decisao BMS: estar no Confia vale a MESMA pontuacao do Selo A+ — sao os dois
// programas de conformidade cooperativa da RFB, e o Confia e ate mais exigente
// (adesao por ADE, com protocolo assinado). Sem nenhum dos dois -> ND.
//
// t_sintonia: 'A+' | 'ND'   (contrato que o Orquestrador pontua)
// sintonia_fonte: selo_sintonia | confia_protocolo | nenhum  (exibicao/auditoria)
// ============================================================================

// Snapshot da lista do Confia (bases de CNPJ, 8 digitos) — atualizado em 2026-08.
// Usado SO quando o download da pagina falha; assim uma queda do gov.br nao
// transforma um fornecedor Confia em ND.
const CONFIA_SNAPSHOT = [
  '62462015', '59476770', '81243735', '02886427', '10456016', '02270689',
  '02302100', '28152650', '59104422', '07047251', '10394422', '33050071',
  '61695227', '55962369', '90400888', '50567288', '43461789', '45985371',
  '08324196', '87235172', '00360305', '00000000', '02914460', '33000167',
  '04817052', '60409075', '76093731', '01358874', '01730520', '75904383',
  '62695036', '60665981', '33657248', '87288940', '24227491', '33611500',
  '89850341'
];

const entrada = $('When Executed by Another Workflow').first().json;
const cnpjBase = String(entrada.cnpj || '')
  .toUpperCase()
  .replace(/[^0-9A-Z]/g, '')
  .padStart(14, '0')
  .substring(0, 8);

let t_sintonia = 'ND';
let sintonia_fonte = 'nenhum';
let confia_lista_origem = 'nao_consultada';
let confia_qtde_lista = null;

// ---------------------------------------------------------------------------
// 1) Selo Sintonia A+
// ---------------------------------------------------------------------------
try {
  const dadosSintonia = $('Receita Sintonia · Consulta Selo A+').first().json?.dados || [];
  if (Array.isArray(dadosSintonia) && dadosSintonia.length > 0) {
    const hoje = new Date();
    const anoMesAtual = hoje.getFullYear() * 100 + (hoje.getMonth() + 1);
    if (Number(dadosSintonia[0].mesValidadeSelo) >= anoMesAtual) {
      t_sintonia = 'A+';
      sintonia_fonte = 'selo_sintonia';
    }
  }
} catch (e) {
  // chamada anterior falhou / formato inesperado -> segue pro fallback
}

// ---------------------------------------------------------------------------
// 2) FALLBACK — lista de protocolos do Confia
// ---------------------------------------------------------------------------
if (t_sintonia === 'ND') {
  let bases = [];

  try {
    const resp = $('Confia · Lista de Protocolos').first().json;
    const html = String(resp?.data ?? resp?.body ?? '');

    if (html.length > 500) {
      // Varre linha a linha da tabela: pega os CNPJs e descarta linhas cuja
      // situacao nao esta ativa.
      const linhas = html.split(/<tr[\s>]/i).slice(1);
      const encontrados = [];
      for (const linha of linhas) {
        const texto = linha.replace(/<[^>]*>/g, ' ').replace(/&nbsp;?/gi, ' ');
        const cnpjs = texto.match(/\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}/g) || [];
        if (cnpjs.length === 0) continue;
        if (/(INATIV|REVOGAD|SUSPENS|CANCELAD|EXCLU|RESCIND)/i.test(texto)) continue;
        for (const c of cnpjs) {
          encontrados.push(c.replace(/\D/g, '').substring(0, 8));
        }
      }
      if (encontrados.length > 0) {
        bases = encontrados;
        confia_lista_origem = 'site';
        // Sanidade: a lista tinha 37 empresas em 2026-08 e so cresce. Se o parser
        // trouxe pouca coisa, o layout provavelmente mudou -> une com o snapshot
        // pra nao perder ninguem (falso ND e pior que um A+ a mais aqui).
        if (encontrados.length < 20) {
          bases = Array.from(new Set([...encontrados, ...CONFIA_SNAPSHOT]));
          confia_lista_origem = 'site+snapshot';
        }
      }
    }
  } catch (e) {
    // node nao executou / erro de parsing -> snapshot
  }

  if (bases.length === 0) {
    bases = CONFIA_SNAPSHOT;
    confia_lista_origem = 'snapshot_local';
  }

  confia_qtde_lista = bases.length;

  if (bases.includes(cnpjBase)) {
    t_sintonia = 'A+';            // mesma pontuacao do Selo Sintonia
    sintonia_fonte = 'confia_protocolo';
  }
}

return [{
  json: {
    t_sintonia,
    sintonia_fonte,
    confia_lista_origem,   // site | snapshot_local | nao_consultada
    confia_qtde_lista,     // quantas empresas ativas a lista trouxe (sanidade do parser)
    cnpj_base_consultado: cnpjBase,
  }
}];
